"use client";

import "./scroll-area.css";

import type React from "react";

import { ScrollArea as BaseScrollArea } from "@base-ui/react/scroll-area";
import { cn } from "tailwind-variants";

import { ScrollAreaContext, useScrollAreaContext } from "./scroll-area.context";
import { scrollAreaVariants, type ScrollAreaVariants } from "./scroll-area.variants";

export type ScrollAreaProps = ScrollAreaVariants & React.ComponentProps<typeof BaseScrollArea.Root>;

export const ScrollAreaRoot = ({ children, className, size, ...props }: ScrollAreaProps) => {
  const slots = scrollAreaVariants({ size });

  return (
    <ScrollAreaContext.Provider value={{ slots }}>
      <BaseScrollArea.Root className={cn(slots.root(), className)} {...props}>
        {children}
      </BaseScrollArea.Root>
    </ScrollAreaContext.Provider>
  );
};

export type ScrollAreaViewportProps = React.ComponentProps<typeof BaseScrollArea.Viewport>;

export const ScrollAreaViewport = ({ className, ...props }: ScrollAreaViewportProps) => {
  const { slots } = useScrollAreaContext();
  return <BaseScrollArea.Viewport className={cn(slots.viewport(), className)} {...props} />;
};

export type ScrollAreaContentProps = React.ComponentProps<typeof BaseScrollArea.Content>;

export const ScrollAreaContent = ({ className, ...props }: ScrollAreaContentProps) => {
  const { slots } = useScrollAreaContext();
  return <BaseScrollArea.Content className={cn(slots.content(), className)} {...props} />;
};

export type ScrollAreaScrollbarProps = React.ComponentProps<typeof BaseScrollArea.Scrollbar>;

export const ScrollAreaScrollbar = ({ className, ...props }: ScrollAreaScrollbarProps) => {
  const { slots } = useScrollAreaContext();
  return <BaseScrollArea.Scrollbar className={cn(slots.scrollbar(), className)} {...props} />;
};

export type ScrollAreaThumbProps = React.ComponentProps<typeof BaseScrollArea.Thumb>;

export const ScrollAreaThumb = ({ className, ...props }: ScrollAreaThumbProps) => {
  const { slots } = useScrollAreaContext();
  return <BaseScrollArea.Thumb className={cn(slots.thumb(), className)} {...props} />;
};

export type ScrollAreaCornerProps = React.ComponentProps<typeof BaseScrollArea.Corner>;

export const ScrollAreaCorner = ({ className, ...props }: ScrollAreaCornerProps) => {
  const { slots } = useScrollAreaContext();
  return <BaseScrollArea.Corner className={cn(slots.corner(), className)} {...props} />;
};

/* eslint-disable perfectionist/sort-objects */

import { tv, type VariantProps } from "tailwind-variants";

export const scrollAreaVariants = tv({
  slots: {
    root: "scroll-area",
    viewport: "scroll-area__viewport",
    content: "scroll-area__content",
    scrollbar: "scroll-area__scrollbar",
    thumb: "scroll-area__thumb",
    corner: "scroll-area__corner",
  },
  variants: {
    size: {
      sm: {
        scrollbar: "scroll-area__scrollbar--sm",
      },
      md: {
        scrollbar: "scroll-area__scrollbar--md",
      },
      lg: {
        scrollbar: "scroll-area__scrollbar--lg",
      },
    },
  },
  defaultVariants: {
    size: "md",
  },
});

export type ScrollAreaVariants = VariantProps<typeof scrollAreaVariants>;

"use client";

import { createContext, useContext } from "react";

import { scrollAreaVariants } from "./scroll-area.variants";

export type ScrollAreaContext = {
  slots: ReturnType<typeof scrollAreaVariants>;
};

export const ScrollAreaContext = createContext<ScrollAreaContext | null>(null);

export const useScrollAreaContext = () => {
  const context = useContext(ScrollAreaContext);
  return context ?? { slots: scrollAreaVariants() };
};

.scroll-area {
  @apply relative overflow-hidden rounded-md border border-border bg-background text-foreground;
}

.scroll-area__viewport {
  @apply h-full w-full rounded-[inherit] outline-none focus-visible:outline-2 focus-visible:outline-ring;
}

.scroll-area__content {
  @apply flex flex-col p-4;
}

.scroll-area__scrollbar {
  @apply flex select-none touch-none p-0.5 bg-muted/30 transition-opacity duration-150 data-[orientation=vertical]:w-2.5 data-[orientation=horizontal]:h-2.5 data-[orientation=horizontal]:flex-col data-hovering:opacity-100 data-scrolling:opacity-100 opacity-0;
}

.scroll-area__scrollbar--sm {
  @apply data-[orientation=vertical]:w-2 data-[orientation=horizontal]:h-2;
}

.scroll-area__scrollbar--md {
  @apply data-[orientation=vertical]:w-2.5 data-[orientation=horizontal]:h-2.5;
}

.scroll-area__scrollbar--lg {
  @apply data-[orientation=vertical]:w-3.5 data-[orientation=horizontal]:h-3.5;
}

.scroll-area__thumb {
  @apply relative flex-1 rounded-full bg-border transition-colors hover:bg-muted-foreground/50;
}

.scroll-area__corner {
  @apply bg-muted;
}

import {
  ScrollAreaContent,
  ScrollAreaCorner,
  ScrollAreaRoot,
  ScrollAreaScrollbar,
  ScrollAreaThumb,
  ScrollAreaViewport,
} from "./scroll-area";

export const ScrollArea = {
  Content: ScrollAreaContent,
  Corner: ScrollAreaCorner,
  Root: ScrollAreaRoot,
  Scrollbar: ScrollAreaScrollbar,
  Thumb: ScrollAreaThumb,
  Viewport: ScrollAreaViewport,
};

export {
  ScrollAreaContent,
  ScrollAreaCorner,
  ScrollAreaRoot,
  ScrollAreaScrollbar,
  ScrollAreaThumb,
  ScrollAreaViewport,
};

export type {
  ScrollAreaContentProps,
  ScrollAreaCornerProps,
  ScrollAreaProps,
  ScrollAreaScrollbarProps,
  ScrollAreaThumbProps,
  ScrollAreaViewportProps,
} from "./scroll-area";
export { ScrollAreaContext, useScrollAreaContext } from "./scroll-area.context";
export { type ScrollAreaVariants, scrollAreaVariants } from "./scroll-area.variants";
